  ('ca3bbb7a-2c69-550c-95b8-cad9f1808de4', '22222222-2222-2222-2222-222222222211', 'mcq', '若𝑥, 𝑦是有理数，且(1 + 2√3)𝑥+ (1 −√3)𝑦−2 + 5√3 = 0, 则𝑥, 𝑦的 值分别是( ).', '[{"key": "A", "text": "1,3"}, {"key": "B", "text": "−1,2"}, {"key": "C", "text": "−1,3"}, {"key": "D", "text": "1,2"}, {"key": "E", "text": "以上结论都不正确"}]'::jsonb, '', '', '数学/第1章 算术1  合订版.pdf', 4, false, 14, null),
  ('faa945aa-0886-5c7b-b042-7bd165fdf5d9', '22222222-2222-2222-2222-222222222211', 'mcq', '一个正数的两个平方根分别为2𝑎−1 和𝑎−2，则这个正数为( ).', '[{"key": "A", "text": "1"}, {"key": "B", "text": "4"}, {"key": "C", "text": "9"}, {"key": "D", "text": "16"}, {"key": "E", "text": "25"}]'::jsonb, '', '', '数学/第1章 算术1  合订版.pdf', 4, false, 15, null),
  ('1ca588a3-8c5d-5f98-9604-e9a1ac30ecbe', '22222222-2222-2222-2222-222222222211', 'mcq', '设𝑎与𝑏之和的倒数的2027 次方等于1，𝑎的相反数与𝑏之和的倒数的 2009 次方也等于1.则𝑎2007 + 𝑏2009 = ( ).', '[{"key": "A", "text": "−1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "1"}, {"key": "D", "text": "0"}, {"key": "E", "text": "−2"}]'::jsonb, '', '', '数学/第1章 算术1  合订版.pdf', 6, false, 16, null),
