  ('89712054-fdf1-54af-83f5-c2f3bc5a572b', '22222222-2222-2222-2222-222222222211', 'mcq', '将9991 个苹果放入大小两种箱子(每种箱子若干个)，刚好放完，每 个大箱子可装4 个,每个小箱子能装若干个，已知小箱子用了1999个， 则大箱子用( )个.', '[{"key": "A", "text": "1998"}, {"key": "B", "text": "1999"}, {"key": "C", "text": "2000"}, {"key": "D", "text": "1996"}, {"key": "E", "text": "1994"}]'::jsonb, '', '', '数学/第1章 算术1  合订版.pdf', 15, false, 41, null),
  ('350d0c30-f58c-56e4-be35-789e4d5395a8', '22222222-2222-2222-2222-222222222211', 'mcq', '三名小孩中有一名学龄前儿童(年龄不足6 岁)，他们的年龄都是质数 (素数)，且依次相差6 岁，则他们的年龄之和为( ).', '[{"key": "A", "text": "21"}, {"key": "B", "text": "27"}, {"key": "C", "text": "33"}, {"key": "D", "text": "39"}, {"key": "E", "text": "51"}]'::jsonb, '', '', '数学/第1章 算术1  合订版.pdf', 17, false, 52, null),
